const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const ids=['width','height','depth','thickness','kerf','modules','split','shelves','lip','lipMode','wallSelect','angleL','angleR','parachute','parachuteDepth','joint','hinge','hingeSize','finger','press','sheetW','sheetH','gap','project'];
const state={angle:-.65,tilt:.48,zoom:1};
const num=id=>+$('#'+id).value;
function params(){return Object.fromEntries(ids.map(id=>[id,$('#'+id).value]))}
function load(){try{const h=location.hash.slice(1);if(!h)return;const p=JSON.parse(decodeURIComponent(atob(h)));ids.forEach(id=>{if(p[id]!=null)$('#'+id).value=p[id]})}catch(e){}}
function moduleWidths(){const n=num('modules'),w=num('width');if(n===1)return[w];if(n===2){const a=Math.round(w*num('split')/100);return[a,w-a]}return [Math.round(w/3),Math.round(w/3),w-2*Math.round(w/3)]}
function fitSlot(){return Math.max(.1,num('thickness')-2*num('kerf')-num('press'))}
function angleOffsets(){const d=num('depth');return [Math.tan((90-num('angleL'))*Math.PI/180)*d,Math.tan((90-num('angleR'))*Math.PI/180)*d]}
function frontTabs(span){return [[30,60],[span/2-15,span/2+15],[span-60,span-30]].filter(x=>x[0]>5&&x[1]<span-5)}
function edgeTabs(d){const f=Math.max(8,num('finger')),n=Math.max(2,Math.floor((d-20)/f));const gap=(d-20)/n;return Array.from({length:Math.ceil(n/2)},(_,i)=>[10+i*gap*2,Math.min(d-10,10+i*gap*2+gap)])}
function polyShelf(w,d,t,tabs,leftInset=0,rightInset=0){const backL=t+leftInset,backR=w-t-rightInset;const p=[[t,0],[w-t,0]];tabs.forEach(([a,b])=>p.push([w-t,a],[w,a],[w-rightInset,b],[backR,b]));p.push([backR,d],[backL,d]);[...tabs].reverse().forEach(([a,b])=>p.push([backL,b],[0,b],[0,a],[t,a]));return p}
function polySide(d,h,t,tabs,skew=0,side='left'){const s=side==='left'?skew:-skew;const p=[[0,t],[s,t]];tabs.forEach(([a,b])=>p.push([a+s,t],[a+s,0],[b+s,0],[b+s,t]));p.push([d+s,t],[d,h-t]);[...tabs].reverse().forEach(([a,b])=>p.push([b,h-t],[b,h],[a,h],[a,h-t]));return p}
function polyFront(w,h,t,tabs){const p=[[0,0],[w,0],[w,h]];[...tabs].reverse().forEach(([a,b])=>p.push([b,h],[b,h+t],[a,h+t],[a,h]));return p.concat([[0,h]])}
function geometry(){
 const d=num('depth'),h=num('height'),t=num('thickness'),s=num('shelves'),lip=num('lip'),gap=num('gap'),slot=fitSlot(),et=edgeTabs(d),[skewL,skewR]=angleOffsets();let parts=[];
 moduleWidths().forEach((mw,mi)=>{
  for(const name of ['TOP','BOTTOM']){let holes=[];[10,mw-15].forEach(x=>et.forEach(([a,b])=>holes.push([x+(t-slot)/2,a+(b-a-(b-a-2*num('kerf')-num('press')))/2,slot,b-a-2*num('kerf')-num('press')] )));parts.push({name:`M${mi+1} ${name}`,kind:'rect',w:mw,h:d,holes})}
  for(const side of ['LEFT','RIGHT']){let holes=[];for(let j=1;j<=s;j++){const y=h*j/(s+1)-slot/2;et.forEach(([a,b])=>holes.push([a+(b-a-(b-a-2*num('kerf')-num('press')))/2,y,b-a-2*num('kerf')-num('press'),slot]))}const skew=side==='LEFT'?skewL:skewR;parts.push({name:`M${mi+1} SIDE ${side}`,kind:'poly',pts:polySide(d,h,t,et,skew,side.toLowerCase()),holes})}
  const span=mw-30,sw=span+2*t;
  for(let j=1;j<=s;j++){let holes=[];if(num('lip')>0&&$('#lipMode').value==='each')frontTabs(span).forEach(([a,b])=>holes.push([t+a+num('kerf'),15-slot/2,b-a-2*num('kerf')-num('press'),slot]));if($('#hinge').value!=='none'&&j===1){const hs=num('hingeSize');if($('#hinge').value==='left'||$('#hinge').value==='both')holes.push([8,Math.max(8,lip/2-hs/2),hs,hs]);if($('#hinge').value==='right'||$('#hinge').value==='both')holes.push([span-8-hs,Math.max(8,lip/2-hs/2),hs,hs])}parts.push({name:`M${mi+1} SHELF ${j}`,kind:'poly',pts:polyShelf(sw,d,t,et,skewL,skewR),holes});if(lip>0&&$('#lipMode').value==='each'){let frontHoles=[];const pd=num('parachuteDepth');if($('#parachute').value==='single')frontHoles.push([span/2-pd/2,lip/2-5,pd,10]);if($('#parachute').value==='double'){frontHoles.push([span*.28-pd/2,lip/2-5,pd,10],[span*.72-pd/2,lip/2-5,pd,10])}parts.push({name:`M${mi+1} FRONT ${j}`,kind:'poly',pts:polyFront(span,lip,t,frontTabs(span)),holes:frontHoles})}}
 });return parts;
}
function dims(p){if(p.kind==='rect')return[p.w,p.h];return[Math.max(...p.pts.map(x=>x[0])),Math.max(...p.pts.map(x=>x[1]))]}
function layout(parts){const sw=num('sheetW'),gap=num('gap');let x=gap,y=gap,row=0;return parts.map(p=>{const [w,h]=dims(p);if(x+w+gap>sw){x=gap;y+=row+gap;row=0}const q={...p,x,y};x+=w+gap;row=Math.max(row,h);return q})}
function pathD(pts,x=0,y=0){return 'M'+pts.map(p=>`${(p[0]+x).toFixed(2)} ${(p[1]+y).toFixed(2)}`).join('L')+'Z'}
function svgString(download=false){const parts=layout(geometry()),sw=num('sheetW'),sh=Math.max(num('sheetH'),...parts.map(p=>p.y+dims(p)[1]+num('gap')));let a=[`<svg xmlns="http://www.w3.org/2000/svg" width="${sw}mm" height="${sh}mm" viewBox="0 0 ${sw} ${sh}">`,`<g fill="none" stroke="#ff0000" stroke-width="0.1">`];parts.forEach(p=>{if(p.kind==='rect')a.push(`<rect x="${p.x}" y="${p.y}" width="${p.w}" height="${p.h}"/>`);else a.push(`<path d="${pathD(p.pts,p.x,p.y)}"/>`);p.holes.forEach(h=>a.push(`<rect x="${(p.x+h[0]).toFixed(2)}" y="${(p.y+h[1]).toFixed(2)}" width="${h[2].toFixed(2)}" height="${h[3].toFixed(2)}"/>`))});a.push('</g><g fill="#1677ff" font-family="sans-serif" font-size="7">');parts.forEach(p=>a.push(`<text x="${p.x+4}" y="${p.y+11}">${p.name}</text>`));a.push('</g></svg>');return a.join('')}
function renderCut(){const parts=layout(geometry()),sh=Math.max(num('sheetH'),...parts.map(p=>p.y+dims(p)[1]+num('gap')));$('#cutPreview').innerHTML=svgString().replace(/^<svg[^>]*>|<\/svg>$/g,'');$('#cutPreview').setAttribute('viewBox',`0 0 ${num('sheetW')} ${sh}`);$('#cutPreview').setAttribute('preserveAspectRatio','xMidYMid meet')}
function project3(x,y,z,cx,cy){const a=state.angle,t=state.tilt,s=.55*state.zoom;const X=x*Math.cos(a)-y*Math.sin(a),Y=(x*Math.sin(a)+y*Math.cos(a))*Math.sin(t)-z*Math.cos(t);return[cx+X*s,cy+Y*s]}
function drawBox(ctx,x,y,z,w,d,h,cx,cy,color){const v=[[x,y,z],[x+w,y,z],[x+w,y+d,z],[x,y+d,z],[x,y,z+h],[x+w,y,z+h],[x+w,y+d,z+h],[x,y+d,z+h]].map(p=>project3(...p,cx,cy));const faces=[[0,1,5,4],[1,2,6,5],[4,5,6,7]];faces.forEach((f,i)=>{ctx.beginPath();f.forEach((k,j)=>j?ctx.lineTo(...v[k]):ctx.moveTo(...v[k]));ctx.closePath();ctx.fillStyle=color+['55','3d','70'][i];ctx.fill();ctx.strokeStyle=color;ctx.lineWidth=1;ctx.stroke()})}
function drawSlantedSide(ctx,x,y,z,d,h,inset,left,cx,cy,color){const backX=left?x+inset:x-inset;const v=[[x,y,z],[backX,y+d,z],[backX,y+d,z+h],[x,y,z+h]].map(p=>project3(...p,cx,cy));ctx.beginPath();v.forEach((p,i)=>i?ctx.lineTo(...p):ctx.moveTo(...p));ctx.closePath();ctx.fillStyle=color+'55';ctx.fill();ctx.strokeStyle=color;ctx.stroke()}
function drawTrapezoid(ctx,x,y,z,w,d,t,leftInset,rightInset,cx,cy,color){const v=[[x,y,z],[x+w,y,z],[x+w-rightInset,y+d,z],[x+leftInset,y+d,z],[x,y,z+t],[x+w,y,z+t],[x+w-rightInset,y+d,z+t],[x+leftInset,y+d,z+t]].map(p=>project3(...p,cx,cy));[[0,1,5,4],[1,2,6,5],[3,0,4,7],[4,5,6,7]].forEach(f=>{ctx.beginPath();f.forEach((k,j)=>j?ctx.lineTo(...v[k]):ctx.moveTo(...v[k]));ctx.closePath();ctx.fillStyle=color+'55';ctx.fill();ctx.strokeStyle=color;ctx.stroke()})}
function render3D(){const c=$('#model'),r=c.getBoundingClientRect(),dpr=devicePixelRatio||1;c.width=r.width*dpr;c.height=r.height*dpr;const ctx=c.getContext('2d');ctx.scale(dpr,dpr);ctx.clearRect(0,0,r.width,r.height);const t=num('thickness'),h=num('height'),dep=num('depth'),cx=r.width/2,cy=r.height*.6,[skewL,skewR]=angleOffsets();let off=-num('width')/2;moduleWidths().forEach((mw,mi)=>{const col=mi%2?'#5fc0ff':'#ffb000';drawTrapezoid(ctx,off,0,0,mw,dep,t,skewL,skewR,cx,cy,col);drawTrapezoid(ctx,off,0,h-t,mw,dep,t,skewL,skewR,cx,cy,col);drawSlantedSide(ctx,off+10,0,t,dep,h-2*t,skewL,true,cx,cy,col);drawSlantedSide(ctx,off+mw-15,0,t,dep,h-2*t,skewR,false,cx,cy,col);for(let j=1;j<=num('shelves');j++){const z=h*j/(num('shelves')+1);drawTrapezoid(ctx,off+15,0,z-t/2,mw-30,dep,t,skewL,skewR,cx,cy,col);if(num('lip')>0&&$('#lipMode').value==='each')drawTrapezoid(ctx,off+15,12.5,z+t/2,mw-30,dep,t,skewL,skewR,cx,cy,'#ff6b4a')}off+=mw+18})}
function download(name,type,data){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([data],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function dxf(){const parts=layout(geometry());let s='0\nSECTION\n2\nENTITIES\n';const line=(a,b)=>`0\nLINE\n8\nCUT\n10\n${a[0]}\n20\n${-a[1]}\n11\n${b[0]}\n21\n${-b[1]}\n`;parts.forEach(p=>{let pts=p.kind==='rect'?[[0,0],[p.w,0],[p.w,p.h],[0,p.h]]:p.pts;pts=pts.map(q=>[q[0]+p.x,q[1]+p.y]);pts.forEach((q,i)=>s+=line(q,pts[(i+1)%pts.length]));p.holes.forEach(h=>{const q=[[h[0],h[1]],[h[0]+h[2],h[1]],[h[0]+h[2],h[1]+h[3]],[h[0],h[1]+h[3]]].map(v=>[v[0]+p.x,v[1]+p.y]);q.forEach((v,i)=>s+=line(v,q[(i+1)%4]))})});return s+'0\nENDSEC\n0\nEOF\n'}
function update(){const p=geometry(),cut=p.reduce((sum,x)=>{const [w,h]=dims(x);return sum+2*(w+h)+x.holes.reduce((a,q)=>a+2*(q[2]+q[3]),0)},0);$('#widthOut').textContent=num('width')+' mm';$('#heightOut').textContent=num('height')+' mm';$('#depthOut').textContent=num('depth')+' mm';$('#splitOut').textContent=num('split')+' / '+(100-num('split'))+' %';$('#slotValue').textContent=fitSlot().toFixed(2).replace('.',',')+' mm';$('#metricSize').textContent=`${num('width')} × ${num('height')} × ${num('depth')}`;$('#metricPieces').textContent=p.length;$('#metricModules').textContent=num('modules');$('#metricCut').textContent=(cut/1000).toFixed(1);$('#splitWrap').style.display=num('modules')===2?'block':'none';render3D();renderCut()}
$$('input,select').forEach(el=>el.addEventListener('input',()=>{if(el.dataset.for){$('#'+el.dataset.for).value=el.value}else{const mirror=$(`[data-for="${el.id}"]`);if(mirror)mirror.value=el.value}update()}));
$$('.tab').forEach(b=>b.onclick=()=>{$$('.tab').forEach(x=>x.classList.remove('active'));b.classList.add('active');$('#modelView').classList.toggle('hidden',b.dataset.view!=='model');$('#cutView').classList.toggle('hidden',b.dataset.view!=='cut');update()});
$('#downloadSvg').onclick=()=>download((($('#project').value||'progetto').replace(/\W+/g,'_'))+'.svg','image/svg+xml',svgString(true));
$('#downloadDxf').onclick=()=>download((($('#project').value||'progetto').replace(/\W+/g,'_'))+'.dxf','application/dxf',dxf());
$('#saveJson').onclick=()=>download('laser-cabinet.json','application/json',JSON.stringify(params(),null,2));
$('#share').onclick=async()=>{const u=location.href.split('#')[0]+'#'+btoa(encodeURIComponent(JSON.stringify(params())));await navigator.clipboard.writeText(u);toast('Link parametrico copiato')};
$('#resetView').onclick=()=>{state.angle=-.65;state.tilt=.48;state.zoom=1;render3D()};
const c=$('#model');let drag=false,lx=0,ly=0;c.onpointerdown=e=>{drag=true;lx=e.clientX;ly=e.clientY;c.setPointerCapture(e.pointerId)};c.onpointermove=e=>{if(!drag)return;state.angle+=(e.clientX-lx)*.008;state.tilt=Math.max(.15,Math.min(1.2,state.tilt+(e.clientY-ly)*.006));lx=e.clientX;ly=e.clientY;render3D()};c.onpointerup=()=>drag=false;c.onwheel=e=>{e.preventDefault();state.zoom=Math.max(.35,Math.min(2,state.zoom*(e.deltaY>0?.9:1.1)));render3D()};
function toast(s){const t=$('#toast');t.textContent=s;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),1800)}
const baseSvgString=svgString;svgString=()=>baseSvgString().replace('<g fill="none" stroke="#ff0000" stroke-width="0.1">','<rect width="100%" height="100%" fill="#fffdf8"/><g fill="none" stroke="#d71920" stroke-width="0.35">');const baseUpdate=update;update=()=>{baseUpdate();const [a,b]=angleOffsets();$('#angleValue').textContent=`${a.toFixed(1)} / ${b.toFixed(1)} mm`;$('#selectedWall').textContent={left:'Sinistra',right:'Destra',top:'Superiore',bottom:'Inferiore'}[$('#wallSelect').value]};
$$('input,select').forEach(el=>el.addEventListener('change',update));
addEventListener('resize',render3D);load();update();
